var n=`0323-confit-de-canard`;var i=`world-0323`;var a=`FR`;var o=`western-europe`;var r=4;var d=897;var u={en:`Confit de Canard`,ua:`Конфі з качки`};var s={en:`A traditional method for duck confit, with curing and slow cooking immersed in duck fat; maintain safe refrigeration.`,ua:`Традиційний метод качиного конфі: попередній посол і тривале приготування у качиному жирі, із дотриманням холодового режиму.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 720 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 720 хвилин.`,t:[`marinating`],m:720,i:[[`duck-leg`,1e3,`g`],[`sea-salt`,32,`g`],[`thyme`,5,`sprig`],[`garlic`,6,`clove`]]},{en:`Submerge the cured, rinsed duck legs in duck fat and cook gently at 110–120°C for about 2¾ hours until the meat is very tender; do not boil the fat.`,ua:`Повністю занурте промиті після засолу качині стегенця у качиний жир і томіть при 110–120°C приблизно 2 години 45 хвилин до м’якості, не допускаючи кипіння жиру.`,t:[`poaching`],m:165,i:[[`duck-fat`,950,`g`]]},{en:`Roast in a preheated 190°C oven for about 12 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 12 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:12,i:[]}];var g={slug:n,id:i,country:`FR`,region:o,servings:4,minutes:897,title:u,text:s,steps:c};export{a as country,g as default,i as id,d as minutes,o as region,r as servings,n as slug,c as steps,s as text,u as title};